begin;
drop policy hub_comment_read on public.hub_comments;
create policy hub_comment_read on public.hub_comments for select to anon,authenticated using((is_sample or auth.uid() is not null) and exists(select 1 from public.hub_posts p where p.id=post_id));
revoke update on public.hub_posts from authenticated;
grant update(title,body,category,department) on public.hub_posts to authenticated;
commit;
begin;
insert into auth.users(id,email,aud,role) values('10000000-0000-4000-8000-000000000001','rls-owner@example.invalid','authenticated','authenticated'),('10000000-0000-4000-8000-000000000002','rls-other@example.invalid','authenticated','authenticated');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into public.hub_profiles(id,display_name,department) values(auth.uid(),'검증용 작성자','DX교육');
insert into public.hub_posts(title,body,category,author_id) values('__RLS_TEST__','검증 후 롤백','업무공유',auth.uid());
update public.hub_posts set body='본인 수정 성공' where title='__RLS_TEST__';
insert into public.hub_comments(post_id,body,author_id) select id,'본인 댓글 검증',auth.uid() from public.hub_posts where title='__RLS_TEST__';
do $$ begin if not exists(select 1 from public.hub_posts where title='__RLS_TEST__' and body='본인 수정 성공' and author_name='검증용 작성자') then raise exception 'owner CRUD failed';end if;end $$;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
do $$ declare n int;begin update public.hub_posts set body='타인 수정' where title='__RLS_TEST__';get diagnostics n=row_count;if n<>0 then raise exception 'other user could edit';end if;delete from public.hub_posts where title='__RLS_TEST__';get diagnostics n=row_count;if n<>0 then raise exception 'other user could delete';end if;end $$;
reset role;set local role anon;select set_config('request.jwt.claims','{}',true);
do $$ begin if exists(select 1 from public.hub_posts where title='__RLS_TEST__') then raise exception 'anonymous could read member post';end if;if exists(select 1 from public.hub_comments where body='본인 댓글 검증') then raise exception 'anonymous could read member comment';end if;if (select count(*) from public.hub_posts)<10 then raise exception 'sample posts unreadable';end if;begin insert into public.hub_posts(title,body,category) values('unauthorized','test','업무공유');raise exception 'anonymous could write';exception when insufficient_privilege then null;end;end $$;
reset role;set local role authenticated;select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
delete from public.hub_comments where body='본인 댓글 검증';delete from public.hub_posts where title='__RLS_TEST__';
do $$ begin if exists(select 1 from public.hub_posts where title='__RLS_TEST__') then raise exception 'owner delete failed';end if;end $$;
reset role;rollback;
select 'PASS: owner CRUD, foreign write blocked, anonymous sample-only read, anonymous write blocked, rollback cleaned test records' as security_test;